/* Ports the symbol and codeword order of reedsolomon.c of the ISO/IEC 14496-5:2001 MPEG-4 Audio epTool (NTT DoCoMo,
 * 1998); MPEG reference software licence, see THIRD-PARTY-NOTICES. Modified for Smalt. */
package com.github.auties00.smalt.audio.aac.internal.ep;

import java.util.Arrays;

/**
 * Encodes and decodes the shortened Reed-Solomon codes SRS(255-l, 255-2k-l) of the MPEG-4 audio error protection
 * tool over GF(2^8) (ISO/IEC 14496-3 subclause 1.8.4.7).
 *
 * <p>The field is generated by {@code x^8+x^4+x^3+x^2+1} and the code by {@code (x-a)(x-a^2)...(x-a^2k)}. A
 * codeword holds the information symbols then the {@code 2k} parity symbols, the first symbol being the highest
 * order coefficient. Decoding corrects up to {@code k} symbol errors (Berlekamp-Massey, Chien search and Forney's
 * formula). Instances keep their work arrays and are not thread-safe.
 */
final class ReedSolomon {
    /**
     * The largest number of correctable symbols: 2k parity symbols must leave room for one information symbol.
     */
    static final int MAX_CORRECTABLE = 127;

    /**
     * The powers of the primitive element, doubled so that a sum of two logarithms indexes it directly.
     */
    private static final int[] EXP = new int[512];

    /**
     * The discrete logarithm of each nonzero field element.
     */
    private static final int[] LOG = new int[256];

    static {
        var x = 1;
        for (var i = 0; i < 255; i++) {
            EXP[i] = x;
            LOG[x] = i;
            x <<= 1;
            if ((x & 0x100) != 0) {
                x ^= 0x11D;
            }
        }
        for (var i = 255; i < 512; i++) {
            EXP[i] = EXP[i - 255];
        }
    }

    /**
     * The syndromes {@code S1} to {@code S2k}.
     */
    private final int[] syndromes = new int[2 * MAX_CORRECTABLE];

    /**
     * The error locator polynomial, lowest order first.
     */
    private final int[] locator = new int[2 * MAX_CORRECTABLE + 1];

    /**
     * The previous locator of the Berlekamp-Massey iteration.
     */
    private final int[] previous = new int[2 * MAX_CORRECTABLE + 1];

    /**
     * A scratch polynomial of the Berlekamp-Massey iteration.
     */
    private final int[] scratch = new int[2 * MAX_CORRECTABLE + 1];

    /**
     * The error evaluator polynomial, lowest order first.
     */
    private final int[] evaluator = new int[2 * MAX_CORRECTABLE];

    /**
     * The positions of the errors the Chien search found.
     */
    private final int[] errorPositions = new int[MAX_CORRECTABLE];

    /**
     * The values of the errors the Chien search found.
     */
    private final int[] errorValues = new int[MAX_CORRECTABLE];

    /**
     * Multiplies two field elements.
     *
     * @param a the first element
     * @param b the second element
     * @return the product
     */
    private static int multiply(int a, int b) {
        return a == 0 || b == 0 ? 0 : EXP[LOG[a] + LOG[b]];
    }

    /**
     * Computes the parity symbols of a run of information symbols.
     *
     * @param symbols the codeword symbols: the information first, the parity written after it
     * @param offset the index of the first symbol
     * @param count the number of information symbols
     * @param correctable the number of correctable symbols {@code k}, from 1 to {@link #MAX_CORRECTABLE}
     */
    static void encode(int[] symbols, int offset, int count, int correctable) {
        var parity = 2 * correctable;
        var generator = new int[parity + 1];
        generator[0] = 1;
        for (var j = 1; j <= parity; j++) {
            for (var i = j; i > 0; i--) {
                generator[i] = generator[i - 1] ^ multiply(generator[i], EXP[j]);
            }
            generator[0] = multiply(generator[0], EXP[j]);
        }
        var remainder = new int[parity];
        for (var i = 0; i < count; i++) {
            var feedback = symbols[offset + i] ^ remainder[parity - 1];
            for (var j = parity - 1; j > 0; j--) {
                remainder[j] = remainder[j - 1] ^ multiply(feedback, generator[j]);
            }
            remainder[0] = multiply(feedback, generator[0]);
        }
        for (var j = 0; j < parity; j++) {
            symbols[offset + count + j] = remainder[parity - 1 - j];
        }
    }

    /**
     * Corrects a codeword in place.
     *
     * @param symbols the codeword symbols
     * @param offset the index of the first symbol
     * @param length the number of symbols, information and parity, at most 255
     * @param correctable the number of correctable symbols {@code k}
     * @return the number of corrected symbols, or -1 when the codeword holds more errors than the code corrects
     */
    int decode(int[] symbols, int offset, int length, int correctable) {
        var parity = 2 * correctable;
        var clean = true;
        for (var j = 0; j < parity; j++) {
            var root = EXP[j + 1];
            var value = 0;
            for (var i = 0; i < length; i++) {
                value = multiply(value, root) ^ symbols[offset + i];
            }
            syndromes[j] = value;
            clean &= value == 0;
        }
        if (clean) {
            return 0;
        }
        var degree = berlekampMassey(parity);
        if (degree > correctable) {
            return -1;
        }
        for (var i = 0; i < parity; i++) {
            var value = 0;
            for (var j = 0; j <= Math.min(i, degree); j++) {
                value ^= multiply(locator[j], syndromes[i - j]);
            }
            evaluator[i] = value;
        }
        var found = 0;
        for (var position = 0; position < length; position++) {
            var power = length - 1 - position;
            var inverse = EXP[(255 - power) % 255];
            var value = 0;
            for (var j = degree; j >= 0; j--) {
                value = multiply(value, inverse) ^ locator[j];
            }
            if (value != 0) {
                continue;
            }
            var numerator = 0;
            for (var j = parity - 1; j >= 0; j--) {
                numerator = multiply(numerator, inverse) ^ evaluator[j];
            }
            var derivative = 0;
            for (var j = degree; j >= 1; j--) {
                if ((j & 1) == 1) {
                    derivative ^= multiply(locator[j], EXP[(LOG[inverse] * (j - 1)) % 255]);
                }
            }
            if (derivative == 0) {
                return -1;
            }
            if (numerator == 0) {
                return -1;
            }
            if (found == degree) {
                return -1;
            }
            errorPositions[found] = position;
            errorValues[found] = EXP[LOG[numerator] + 255 - LOG[derivative]];
            found++;
        }
        if (found != degree) {
            return -1;
        }
        for (var i = 0; i < found; i++) {
            symbols[offset + errorPositions[i]] ^= errorValues[i];
        }
        return found;
    }

    /**
     * Runs the Berlekamp-Massey algorithm over {@link #syndromes}, leaving the error locator in {@link #locator}.
     *
     * @param count the number of syndromes
     * @return the degree of the locator
     */
    private int berlekampMassey(int count) {
        Arrays.fill(locator, 0, count + 1, 0);
        Arrays.fill(previous, 0, count + 1, 0);
        locator[0] = 1;
        previous[0] = 1;
        var degree = 0;
        var shift = 1;
        var last = 1;
        for (var n = 0; n < count; n++) {
            var discrepancy = syndromes[n];
            for (var i = 1; i <= degree; i++) {
                discrepancy ^= multiply(locator[i], syndromes[n - i]);
            }
            if (discrepancy == 0) {
                shift++;
                continue;
            }
            var factor = multiply(discrepancy, EXP[255 - LOG[last]]);
            if (2 * degree <= n) {
                System.arraycopy(locator, 0, scratch, 0, count + 1);
                for (var i = 0; i + shift <= count; i++) {
                    locator[i + shift] ^= multiply(factor, previous[i]);
                }
                degree = n + 1 - degree;
                System.arraycopy(scratch, 0, previous, 0, count + 1);
                last = discrepancy;
                shift = 1;
            } else {
                for (var i = 0; i + shift <= count; i++) {
                    locator[i + shift] ^= multiply(factor, previous[i]);
                }
                shift++;
            }
        }
        return degree;
    }
}
